app.MapGet("/sessoes/{id:int}", (int id) =>
    id == 1
        ? Results.Ok(new { id, minutos = 25 })
        : Results.NotFound());
app.Run();

bool EhSessaoDeFoco(int minutos) => minutos > 25;
// Regra combinada: 25 ou mais deve ser foco.
Console.WriteLine(EhSessaoDeFoco(25)); // obtido: false
// esperado: true; a fronteira revela o defeito.
